-- Datos de práctica JDBC para el proyecto RepasoJDBC
-- Tabla única: excusas inventadas para justificar entregas tardías.

DROP TABLE IF EXISTS `excusa_entrega`;

CREATE TABLE `excusa_entrega` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `alumno` VARCHAR(80) NOT NULL,
  `curso` VARCHAR(20) NOT NULL,
  `excusa` VARCHAR(255) NOT NULL,
  `dias_retraso` INT NOT NULL,
  `credibilidad` TINYINT NOT NULL,
  `fecha_entrega` DATE DEFAULT NULL,
  `aprobada_por_profesor` BOOLEAN NOT NULL DEFAULT FALSE,
  `nivel_drama` TINYINT NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

